  "progress": {
    dir: "progress",
    category: "atoms",
    examples: [
      { label: "Default", code: "<Progress value={0.6} />", render: e_atoms_progress_example_0 },
      { label: "Live", code: "<Ticker values={[0, 0.15, 0.4, 0.65, 0.85, 1]}>\n  {(value) => (\n    <Progress showValue value={value}>Uploading…</Progress>\n  )}\n</Ticker>", render: e_atoms_progress_example_1 },
      { label: "Determinate", code: "<Progress value={0.4} />", render: e_atoms_progress_example_2 },
      { label: "Indeterminate", code: "<Progress indeterminate />", render: e_atoms_progress_example_3 },
      { label: "Small", code: "<Progress small value={0.6} />", render: e_atoms_progress_example_4 },
      { label: "Large", code: "<Progress large value={0.6} />", render: e_atoms_progress_example_5 },
      { label: "Warning", code: "<Progress warning showValue value={0.85}>Storage used</Progress>", render: e_atoms_progress_example_6 },
      { label: "Danger", code: "<Progress danger showValue value={1}>Over the WIP limit</Progress>", render: e_atoms_progress_example_7 },
    ],
    donts: [
      { title: "Determinate", do: { caption: "Use a determinate bar when you know the share of work done, and pass `showValue` so the control renders the percent on the label line; the number and the bar always agree.", code: "<Progress showValue value={0.72}>Uploading…</Progress>", render: e_atoms_progress_dont_0_do }, dont: { caption: "Don't park a determinate bar at a hard-coded value as a decorative divider; a frozen fill reads as a stalled task.", code: "<View style={{ gap: 8 }}>\n  <Text style={{ fontSize: 14, lineHeight: 20, color: tokens.foreground }}>Section</Text>\n  <Progress value={0.5} />\n</View>", render: e_atoms_progress_dont_0_dont } },
      { title: "Indeterminate", do: { caption: "Reach for `indeterminate` only when the duration is genuinely unknown. Pass the label as children; on the web and Android a short bar sweeps the track; on iOS the control renders the kit Spinner, the platform's unknown-duration idiom (iOS has no linear indeterminate bar).", code: "<Progress indeterminate>Connecting…</Progress>", render: e_atoms_progress_dont_1_do }, dont: { caption: "Don't fake indeterminate progress when you do have a measurable value; hiding a known value behind a sweep (or a spinner on iOS) hides information you could show.", code: "<View style={{ gap: 8 }}>\n  <Text style={{ fontSize: 14, lineHeight: 20, color: tokens[\"muted-foreground\"] }}>Step 3 of 4</Text>\n  <Progress indeterminate />\n</View>", render: e_atoms_progress_dont_1_dont } },
      { title: "Context", do: { caption: "Give the bar a label through its own `children`; it already renders at the standard field width, and `narrow`, `wide`, or `block` adjust its measure when the layout calls for it.", code: "<Progress value={0.35}>Importing contacts</Progress>", render: e_atoms_progress_dont_2_do }, dont: { caption: "Don't hand-roll a bar from raw views; the kit's `Progress` already adapts its thickness, ends, and track anatomy per platform and stays themed.", code: "<View style={{ width: 320, maxWidth: \"100%\", height: 8, borderRadius: 4, backgroundColor: alpha(tokens.primary, 0.2), overflow: \"hidden\" }}>\n  <View style={{ height: \"100%\", width: \"35%\", borderRadius: 4, backgroundColor: tokens.primary }} />\n</View>", render: e_atoms_progress_dont_2_dont } },
    ],
  },
