    donts: [
      { title: "text", do: { caption: "Vary the line widths and shorten the last line so it reads like real wrapped text.", code: "<Column snug style={{ width: 320 }}>\n  <Skeleton text animate style={{ width: \"100%\" }} />\n  <Skeleton text animate style={{ width: \"95%\" }} />\n  <Skeleton text animate style={{ width: \"60%\" }} />\n</Column>", render: e_atoms_skeleton_dont_0_do }, dont: { caption: "Three full-width lines read as a solid block, not as a paragraph of prose.", code: "<View style={{ width: 320, flexDirection: \"column\", gap: 6 }}>\n  <Skeleton text animate style={{ width: \"100%\" }} />\n  <Skeleton text animate style={{ width: \"100%\" }} />\n  <Skeleton text animate style={{ width: \"100%\" }} />\n</View>", render: e_atoms_skeleton_dont_0_dont } },
      { title: "avatar", do: { caption: "Match the avatar's circle exactly so the photo drops in with no shift.", code: "<Skeleton avatar animate />", render: e_atoms_skeleton_dont_1_do }, dont: { caption: "A square placeholder for a round avatar snaps shape the instant the image loads.", code: "<View style={{ backgroundColor: tokens.muted, borderRadius: 6, width: 40, height: 40 }} />", render: e_atoms_skeleton_dont_1_dont } },
      { title: "button", do: { caption: "Size the placeholder to the button's real height and width.", code: "<Skeleton button animate />", render: e_atoms_skeleton_dont_2_do }, dont: { caption: "An oversized bar overstates a button and the layout jumps when the real control mounts.", code: "<View style={{ backgroundColor: tokens.muted, width: 320, height: 72, borderRadius: 6 }} />", render: e_atoms_skeleton_dont_2_dont } },
      { title: "card", do: { caption: "Mirror the real layout (avatar circle, text lines) so the swap is seamless.", code: "<Skeleton card animate />", render: e_atoms_skeleton_dont_3_do }, dont: { caption: "A generic block that ignores the content's shape causes a jarring shift when it loads.", code: "<View style={{ backgroundColor: tokens.muted, borderRadius: 6, width: 320, height: 88 }} />", render: e_atoms_skeleton_dont_3_dont } },
      { title: "list", do: { caption: "Repeat a per-row placeholder so the avatar-and-text rhythm matches the loaded list.", code: "<Skeleton list animate />", render: e_atoms_skeleton_dont_4_do }, dont: { caption: "One tall block hides the row rhythm, so the list reflows when each item appears.", code: "<View style={{ backgroundColor: tokens.muted, width: 400, height: 120, borderRadius: 6 }} />", render: e_atoms_skeleton_dont_4_dont } },
      { title: "table", do: { caption: "Lay placeholders out on the real column grid so each cell stays put when it fills in.", code: "<Skeleton table animate />", render: e_atoms_skeleton_dont_5_do }, dont: { caption: "A single rectangle gives no column structure; cells shift sideways once data lands.", code: "<View style={{ backgroundColor: tokens.muted, width: 400, height: 120, borderRadius: 6 }} />", render: e_atoms_skeleton_dont_5_dont } },
    ],
